  {!!absolStep&&!dialogue&&!screen&&!battleResult&&<Sheet title={absolStep===1?'Emma':absolStep===2?'앱솔':'AZ'} close={()=>{}} dismissible={false} story><div className="adv-absol-scene"><div className="adv-absol-cast" aria-label="Emma와 AZ, 앱솔"><div className="adv-absol-people"><span>Emma</span><span>AZ</span></div><PokemonImage mon={{id:359,name:'앱솔'}} variant="sprite" eager/></div><p aria-live="polite">{absolStep===1?'트레이너도 없이 갑자기 메가진화하는 포켓몬이 있어요. 포켓몬도 무척 괴로워한답니다.':absolStep===2?'앱솔이 다가와 함께하고 싶다는 듯 바라본다. 앱솔이 동료가 되었다!':'앱솔을 도와줘서 고맙네. 앱솔나이트와 메가링을 받아 주게.'}</p><button className="primary" disabled={busy} onClick={()=>void act('advanceAbsolScene',{step:absolStep})}>{absolStep===3?'이야기 마치기':'다음'}</button></div></Sheet>}
  {!!mission15Step&&!dialogue&&!screen&&!battleResult&&<Sheet title="L" close={()=>{}} dismissible={false} story><div className="adv-l-scene"><div className="adv-l-scene-cast" aria-label="L과 지가르데"><div className="adv-l-figure" aria-label="L"><span>L</span><i/><b/></div><PokemonImage mon={{id:10118,name:'지가르데'}} variant="sprite" eager/></div><p aria-live="polite">{mission15Step===1?'지가르데가 옥상에서 도시를 바라본다. L이 곁으로 다가왔다.':mission15Step===2?'폭주 메가진화에 휘말린 포켓몬들을 또 구해 주었군.':'Emma가 나를 쫓고 있어. 내 진짜 뜻을 알아주면 좋을 텐데…'}</p><button className="primary" disabled={busy} onClick={()=>void act('mission15AdvanceL',{step:mission15Step})}>{mission15Step===3?'이야기 마치기':'다음'}</button></div></Sheet>}
